To every crossed simplicial group $\Delta \mathfrak{G}$, we can associate a sequence of groups
\begin{equation} \mathfrak{G}_n = \operatorname{Aut}\nolimits_{\Delta\mathfrak{G}}([n]). 
\end{equation}

Further, by Property (2), any diagram
\[
	\xymatrix{ & [n]\ar[d]^{g} \\ [m] \ar[r]_{\phi} & [n]}
\]
where $\phi$ in $\Delta$ and $g \in \mathfrak{G}_n$, can be uniquely completed to a commutative diagram in
${\Delta \mathfrak{G}}$
\begin{equation} \xymatrix{ [m]\ar[d]_{\phi^*g} \ar[r]^{g^*\phi} & [n]\ar[d]^{g} \\ [m] \ar[r]_{\phi} & [n]}
\end{equation}
with $g^*\phi$ in $\Delta$ and $\phi^* g \in \mathfrak{G}_n$.

Let $J$ be a finite set. A {\em signed linear order} on $J$ consists of
\begin{enumerate}
	\item a linear order on $J$,
	\item a map of sets $\varepsilon: J \to \mathbb{Z}/2\mathbb{Z}$.
\end{enumerate}

Therefore, we can lift $\lambda(g) \in S_{n+1}$ to a signed permutation 
	\[
		\widetilde{\lambda}(g) = (\varepsilon_0, \varepsilon_1, \dots, \varepsilon_n ;
		\lambda(g)) \in \mathbb{Z}/2\mathbb{Z} \wreath S_{n+1}
	\]
	where 
	\[
		\varepsilon_i = \begin{cases} 0 & \text{if $\lambda(s_j^*g): \{i,i+1\} \to \{j,j+1\}$ is order preserving,}\\
						1 & \text{if $\lambda(s_j^*g): \{i,i+1\} \to \{j,j+1\}$ is order reversing.}
				\end{cases}
	\]

Any $\widetilde G\in\operatorname{Con}(G)$ gives rise to subgroups
\begin{equation} \begin{gathered}
		\widetilde P \,\,=\,\,\pi_0(\widetilde G)\,\, \subset\,\, P\,\,=\,\,\pi_0(G),
		\\
		\widetilde A \,\,=\,\, \pi_1(\widetilde G_e,e)\,\, \subset\,\, A\,\,=\,\,\pi_1(G_e,e),
	\end{gathered}
\end{equation}
with $\widetilde A$ being $P$-invariant.

We have the transformation $\tau_n: \operatorname{NC}_n^F{\EuScript C} \to\operatorname{NC}_n^F{\EuScript C}$ sending such a diagram to
  \begin{equation} F^{-1}(x_n) \buildrel F^{-1}(a_n)\over\longrightarrow x_0  
  \buildrel a_0\over  \longrightarrow x_1\buildrel a_1\over \longrightarrow \cdots
  \buildrel a_{n-2}\over\longrightarrow x_{n-1}
  \buildrel a_{n-1}\over \longrightarrow x_n =  F(F^{-1}(x_n)). 
  \end{equation}

We introduce a larger category ${\mathcal G}$ of ${\Delta \mathfrak{G}}$-structured finite sets, fitting into a diagram
of functors with vertical arrows being surjective on objects and horizontal arrows being
equivalences of categories:
\begin{equation} \xymatrix{
		{\Delta \mathfrak{G}} \ar[d]_\lambda  \ar[r]^\epsilon& {\mathcal G} \ar[d]^{\lambda_{{\mathcal G}}}\\
		{\bf N}\ar[r]& {\bf FSet}
	}
\end{equation}
here ${\bf FSet}$ is the category of all nonempty finite sets, $\bf N \subset {\bf FSet}$ is the full
subcategory on the standard objects $\{0,1,\dots, n\}$, and $\lambda$ is the functor from
Proposition \ref {prop:forget}.

