of automorphisms of the given $\mathbb{G}$-structure $F$ on $S-(M\cap S^\circ)$. This group was described
in Proposition ef {prop:G-structures} (a1)(b1), in particular it is abelian.

Since the embedding \eqref{eq:emb-conf}
is a homotopy equivalence, the categories of connective coverings of $GL(2,\mathbb{R})$ and ${\operatorname{Conf}}(2)$
are equivalent by Proposition \ref {prop:summary-covers}(c).

By Proposition \ref {prop:prod-of-grpds} we have
 \begin{equation} G_{\operatorname{conf}}\operatorname{Str}(S,M)\,\,\simeq \,\, \mathbb{G}\operatorname{Str}(S-(M\cap S^\circ))\times O(2)_{\operatorname{conf}}\operatorname{Str}(S). 
 \end{equation}

Let $(S, M)$ be a stable marked surface. The {\em moduli spaces} of $G_{\operatorname{conf}}$-structures on
$(S,M)$ are defined as the groupoid quotients
 \begin{equation}
\begin{gathered}
\mathcal{M}^{G_{\operatorname{conf}}}(S,M) \,\,=\,\, \operatorname{Diff}(S,M) \bigl\backslash \hskip -.1cm \bigl\backslash G_{\operatorname{conf}}\operatorname{Str}(S,M)),  \\
\mathcal{M}^{G_{\operatorname{conf}}}_{\operatorname{pure}} (S,M) \,\,=\,\, \operatorname{Diff}_{\operatorname{pure}}(S,M) \bigl\backslash \hskip -.1cm \bigl\backslash G_{\operatorname{conf}}\operatorname{Str}(S,M). 
\end{gathered}
\end{equation}

Using  \eqref{eq:prod-str}, we have
\begin{align*}
\mathcal{M}^{G_{\operatorname{conf}}}(S,M) & = \operatorname{Diff}(S,M) \bigl\backslash \hskip -.1cm \bigl\backslash \bigl( \mathbb{G}\operatorname{Str}(S-(M\cap S^\circ)) \times O(2)_{\operatorname{conf}}\operatorname{Str}(S)\bigr)\\
& = \operatorname{Diff}(S,M) \biggl\backslash \hskip -.25cm \biggl\backslash \coprod_{ \{F\}\in \mathbb{G}\operatorname{Str}(S-(M\cap S^\circ))} O(2)_{\operatorname{conf}}\operatorname{Str}(S)\\
& = \coprod _{ \{F\}\in \operatorname{Diff}(S,M) \backslash \hskip -.1cm \backslash \mathbb{G}\operatorname{Str}(S-(M\cap S^\circ))} \biggl( \operatorname{Stab}(F) \bigl\backslash \hskip -.1cm \bigl\backslash O(2)_{\operatorname{conf}}\operatorname{Str}(S)\biggr).
\end{align*}

